# ==============================================================================
# SHINY DASHBOARD: NIH Retraction Cost 
# ==============================================================================
# Reads three pre-processed CSVs that the Python pipeline produces and renders
# a multi-tab dashboard. CPI data is loaded from a cached CSV (annual_cpi.csv)
# regenerated by the weekly pipeline; this avoids a network call to FRED on
# every cold start of the app on shinyapps.io.
# ==============================================================================

# 1. LIBRARIES & GLOBAL SETUP
# ------------------------------------------------------------------------------
library(shiny)
library(tidyverse)
library(scales)
library(lubridate)
library(DT)
library(plotly)
library(shinycssloaders)

# --- INPUT FILES ---
papers_file  <- "data/processed/FINAL_Retractions_Costs_and_Pubs.csv"
authors_file <- "data/processed/Author_Funding_Matches.csv"
cpi_file     <- "data/processed/annual_cpi.csv"
grant_keep_file <- "data/processed/author_grant_keep.csv"  # built by build_collision_flags.R

# --- ANNUAL CPI ---
# Primary source: cached CSV produced by src/cpi_fetcher.py (weekly cron).
# Fallback (only if the CSV is missing): live FRED pull via quantmod, kept as a
# safety net so the app still works in a fresh local clone.
load_annual_cpi <- function(path = cpi_file) {
  
  if (file.exists(path)) {
    df <- readr::read_csv(path, show_col_types = FALSE)
    if (!"Inflation_Multiplier" %in% colnames(df)) {
      current_cpi <- max(df$CPI, na.rm = TRUE)
      df$Inflation_Multiplier <- current_cpi / df$CPI
    }
    return(df[, c("Fiscal_Year", "CPI", "Inflation_Multiplier")])
  }
  
  warning(
    "annual_cpi.csv not found; falling back to live FRED download. ",
    "Run `python -m src.cpi_fetcher` to generate the cache."
  )
  
  if (!requireNamespace("quantmod", quietly = TRUE)) {
    install.packages("quantmod", repos = "https://cloud.r-project.org")
  }
  
  cpi_xts <- quantmod::getSymbols("CPIAUCSL", src = "FRED", auto.assign = FALSE)
  monthly <- data.frame(Date = zoo::index(cpi_xts), CPI = as.numeric(cpi_xts))
  annual <- monthly %>%
    mutate(Fiscal_Year = lubridate::year(Date)) %>%
    group_by(Fiscal_Year) %>%
    summarise(CPI = mean(CPI, na.rm = TRUE), .groups = "drop")
  
  current_cpi <- max(annual$CPI, na.rm = TRUE)
  annual %>% mutate(Inflation_Multiplier = current_cpi / CPI)
}

annual_cpi <- load_annual_cpi()

# --- LOAD PAPERS ---
df_papers <- read_csv(papers_file, show_col_types = FALSE) %>%
  mutate(
    Publication_Year = as.numeric(str_extract(OriginalPaperDate, "(?<=/)\\d{4}")),
    Retraction_Year  = as.numeric(str_extract(RetractionDate,    "(?<=/)\\d{4}")),
    retraction_lag   = Retraction_Year - Publication_Year,
    # Single source of truth: a paper is "NIH Funded" if it has any positive NIH funding.
    Funding_Status   = ifelse(!is.na(Total_NIH_Funding_Cost) & Total_NIH_Funding_Cost > 0,
                              "NIH Funded", "Not NIH Funded / Other"),
    attributed_cost_raw = ifelse(
      !is.na(Total_Grant_Pubs) & Total_Grant_Pubs > 0,
      Total_NIH_Funding_Cost / Total_Grant_Pubs,
      NA
    )
  ) %>%
  left_join(annual_cpi, by = c("Publication_Year" = "Fiscal_Year")) %>%
  mutate(attributed_cost_adjusted = attributed_cost_raw * Inflation_Multiplier)

# Helper: data-driven y-axis limits starting at zero (top-padded so points don't touch frame)
add_margin <- function(v, pad = 0.10) {
  c(0, max(v, na.rm = TRUE) * (1 + pad))
}

# Helper: abbreviated dollar formatter (e.g., $1.23B, $755K)
dollar_short <- scales::label_dollar(accuracy = 0.01, scale_cut = scales::cut_short_scale())

# Helper: format p-values for inline reporting
fmt_p <- function(p) {
  if (is.na(p)) return("NA")
  if (p < 0.001) "p &lt; 0.001" else sprintf("p = %.3f", p)
}

# --- LOAD AUTHORS ---
df_authors_raw <- read_csv(authors_file, show_col_types = FALSE)

author_retractions <- df_authors_raw %>%
  group_by(Original_Author_Name) %>%
  summarise(Num_Retractions = n_distinct(Record_ID), .groups = "drop")

# Grant-level name-collision filter (built by build_collision_flags.R), matching the manuscript.
# Common author names can match the grant records of several different NIH investigators; for an
# author whose name collides with more than one investigator we keep only the grants belonging to
# the real person's PI_ID (anchored by the institution on their retracted paper; PI_ID is stable
# across institution moves) and drop grants held by same-named others. Non-collision authors keep
# every grant. If the artefact is missing, fall back to no filtering so the app still runs.
grant_keep <- tryCatch(read_csv(grant_keep_file, show_col_types = FALSE),
                       error = function(e) NULL)

df_authors <- df_authors_raw %>%
  group_by(Original_Author_Name) %>%
  mutate(First_Retraction_Year = min(Retraction_Year, na.rm = TRUE)) %>%
  ungroup() %>%
  mutate(diff_retracted = Fiscal_Year - First_Retraction_Year)

# Apply the grant-level collision filter (drop grants belonging to same-named other investigators)
# before collapsing to distinct author-grant-year rows. Skipped if the artefact is unavailable.
if (!is.null(grant_keep)) {
  df_authors <- df_authors %>%
    left_join(grant_keep, by = c("Original_Author_Name", "Grant_ID")) %>%
    filter(coalesce(keep_consequences, TRUE))
}

df_authors <- df_authors %>%
  distinct(Original_Author_Name, First_Retraction_Year, Grant_ID, Fiscal_Year, Funding_Amount, diff_retracted) %>%
  left_join(annual_cpi, by = "Fiscal_Year") %>%
  mutate(Funding_Adjusted = Funding_Amount * Inflation_Multiplier) %>%
  left_join(author_retractions, by = "Original_Author_Name")

# Restrict the author-consequences cohort to authors whose first retraction is early
# enough that a full +3-year post-retraction window is observable given the latest
# fiscal year available in RePORTER. Without this restriction, authors retracted in
# the last 3 years contribute $0 to post-retraction offsets for years that have not
# yet happened, artificially inflating the apparent funding drop.
latest_fiscal_year     <- max(df_authors$Fiscal_Year, na.rm = TRUE)
retraction_cutoff_year <- latest_fiscal_year - 3
df_authors <- df_authors %>% filter(First_Retraction_Year <= retraction_cutoff_year)

# --- GRANT-LEVEL DIRECT COST (Summary tab) ---
# Mirrors the "Direct cost to the NIH" section of policy_analysis.qmd. Two measures beyond the
# per-paper attributed cost:
#   (2) total_cost_unique_grants -> full nominal award of every DISTINCT NIH grant behind a
#       retracted paper, counted once (a grant can yield several retracted papers, so summing
#       across paper rows would double-count shared grants).
#   (4) total_cost_personal_pi   -> of those distinct grants, only investigator-held
#       research/career/fellowship awards (codes R/K/F + DP1/2/5) for which a retracted author is
#       the PI. Excludes institutional center/infrastructure funding (P30, U01, P01, training...).
cpi_year <- max(annual_cpi$Fiscal_Year, na.rm = TRUE)

# (2) Distinct-grant nominal cost, no double counting. Funding_Info_cleaned (grant IDs) and
# Individual_NIH_Grant_Costs (matching awards) are ";"-separated, aligned position-for-position.
grant_costs <- df_papers %>%
  filter(Funding_Status == "NIH Funded") %>%
  transmute(mult = Inflation_Multiplier,
            pair = map2(str_split(Funding_Info_cleaned, ";"),
                        str_split(Individual_NIH_Grant_Costs, ";"),
                        ~ tibble(grant = str_trim(.x), gcost = as.numeric(str_trim(.y))))) %>%
  unnest(pair) %>%
  filter(!is.na(grant), grant != "", !is.na(gcost)) %>%
  # Collapse to one row per DISTINCT grant: gcost = first() (a grant carries the same award in
  # every paper citing it); mult = mean() of the citing papers' CPI multipliers (a grant has no
  # single base year to deflate from).
  group_by(grant) %>% summarise(gcost = first(gcost), mult = mean(mult, na.rm = TRUE), .groups = "drop")
mult_fallback <- mean(grant_costs$mult[is.finite(grant_costs$mult)])
grant_costs   <- grant_costs %>% mutate(mult = ifelse(is.finite(mult), mult, mult_fallback))
n_unique_grants          <- nrow(grant_costs)
total_cost_unique_grants <- sum(grant_costs$gcost)

# (3) Recover each grant's NIH activity code (R01, P30, ...) to flag "personal" investigator awards.
# The code is not in Funding_Info_cleaned but is in the raw Funding_Info text (e.g. "(R01 CA203737)")
# and in the authors file's full Grant_ID (e.g. "K08HL086671"). Prefer Funding_Info, else authors.
code_pat <- "([A-Z][A-Z0-9]{2})\\s*([A-Z]{2})([0-9]{4,})"
fi_map <- df_papers %>% filter(Funding_Status == "NIH Funded") %>%
  transmute(m = str_match_all(Funding_Info, code_pat)) %>%
  mutate(p = map(m, ~ tibble(grant = paste0(.x[, 3], .x[, 4]), act = .x[, 2]))) %>%
  select(p) %>% unnest(p) %>%
  distinct(grant, act) %>% group_by(grant) %>% summarise(act_fi = first(act), .groups = "drop")
au_map <- df_authors_raw %>%
  transmute(m = str_match(Grant_ID, code_pat)) %>%
  transmute(grant = paste0(m[, 3], m[, 4]), act = m[, 2]) %>%
  filter(!is.na(act)) %>% distinct(grant, act) %>%
  group_by(grant) %>% summarise(act_au = first(act), .groups = "drop")
grants_typed <- grant_costs %>%
  left_join(fi_map, by = "grant") %>% left_join(au_map, by = "grant") %>%
  mutate(activity = toupper(coalesce(act_fi, act_au)),
         personal = coalesce((str_detect(activity, "^[RKF]") &
                              !activity %in% c("K12", "KL2", "R24", "R25", "R41", "R42", "R43", "R44", "RL1")) |
                             activity %in% c("DP1", "DP2", "DP5"), FALSE))

# (4) Keep only the personal grants for which a retracted author is the PI (grant "core" = IC +
# serial appears in the author-funding matches, i.e. the retracted author holds it, not merely
# acknowledged). These are investigator-held, PI-attributed dollars.
pi_cores <- df_authors_raw %>%
  transmute(core = str_extract(Grant_ID, "[A-Z]{2}[0-9]{4,}$")) %>%
  filter(!is.na(core)) %>% distinct(core) %>% pull(core)
personal_pi <- grants_typed$personal & grants_typed$grant %in% pi_cores
total_cost_personal_pi     <- sum(grants_typed$gcost[personal_pi])                        # nominal $
total_cost_personal_pi_adj <- sum((grants_typed$gcost * grants_typed$mult)[personal_pi])  # CPI-adjusted $
n_grants_personal_pi       <- sum(personal_pi)

# --- GLOBAL PLOT THEME ---
# Transparent backgrounds so plots blend with the dashboard cards.
dashboard_theme <- theme_classic(base_size = 12) +
  theme(
    legend.position  = "top",
    legend.title     = element_blank(),
    plot.background  = element_rect(fill = "transparent", color = NA),
    panel.background = element_rect(fill = "transparent", color = NA),
    panel.grid.major.y = element_line(color = "gray90", linewidth = 0.5)
  )

corporate_colors <- c("NIH Funded" = "#005b96",
                      "Not NIH Funded / Other" = "gray70")

# Finalize a paper-level card plot (Article Characteristics tab). On shinyapps.io plotly can
# mis-size a ggplotly rendered inside an initially-hidden / narrow tab, leaving the panel shifted
# to the right. Forcing a full x-domain, an explicit/auto left margin, a left-anchored top legend
# (no negative-x reservation) and responsive sizing -- together with the tab-shown resize hook in
# the header -- keeps every plot filling its card. `left` is the base left margin; automargin
# expands it for the horizontal bar charts whose category labels need more room.
finalize_card_plot <- function(gg, left = 55) {
  ggplotly(gg, tooltip = c("x", "y", "fill")) %>%
    layout(legend = list(orientation = "h", x = 0, xanchor = "left", y = 1.12, title = list(text = "")),
           margin = list(l = left, r = 25, t = 55, b = 45),
           xaxis = list(domain = c(0, 1), automargin = TRUE),
           yaxis = list(automargin = TRUE),
           autosize = TRUE) %>%
    config(responsive = TRUE)
}

# --- Figure-1-style within-author difference boxplots (shared logic with policy_analysis.qmd) -
# For each author and year offset, the change in value (funding $ or active-grant count) vs.
# that author's value at year -3 (a within-author subtraction, defined for the full cohort;
# year -3 is identically 0). Drawn as a decomposed boxplot coloured by period.
make_diff_box_data <- function(per_author_value, cohort_names, value_col = "Annual_Funding") {
  grid <- tidyr::crossing(Original_Author_Name = cohort_names, diff_retracted = -3:3) %>%
    left_join(per_author_value, by = c("Original_Author_Name", "diff_retracted")) %>%
    mutate(.val = ifelse(is.na(.data[[value_col]]), 0, .data[[value_col]]))
  baseline <- grid %>% filter(diff_retracted == -3) %>% transmute(Original_Author_Name, Baseline = .val)
  grid %>% left_join(baseline, by = "Original_Author_Name") %>%
    mutate(Funding_Diff = .val - Baseline)
}
box_stats <- function(box_data) box_data %>%
  group_by(diff_retracted) %>%
  summarise(p10 = quantile(Funding_Diff, 0.10), p25 = quantile(Funding_Diff, 0.25),
            p50 = median(Funding_Diff), p75 = quantile(Funding_Diff, 0.75),
            p90 = quantile(Funding_Diff, 0.90), .groups = "drop")
mean_line <- function(box_data) box_data %>%
  group_by(diff_retracted) %>% summarise(Funding_Diff = mean(Funding_Diff), .groups = "drop")
# Tight y-axis fit to the visible whiskers (10th-90th pct) + mean, small 5% margin.
whisker_cap <- function(stat_data, mean_data) {
  lo <- min(c(stat_data$p10, mean_data$Funding_Diff), na.rm = TRUE)
  hi <- max(c(stat_data$p90, mean_data$Funding_Diff), na.rm = TRUE)
  pad <- 0.05 * (hi - lo); if (!is.finite(pad) || pad == 0) pad <- 1
  c(lo - pad, hi + pad)
}
# Decomposed boxplot (no box outline): green = pre-retraction (-3..0), orange = post (1..3),
# with the mean change overlaid as a black line + points. Returns a ggplot for ggplotly.
make_box_panel_app <- function(stat_data, mean_data, y_cap, y_label, dollar_y = TRUE) {
  period_pal <- c("Pre-retraction" = "#00716f", "Post-retraction" = "#d16b2a")
  bw <- 0.6
  fmt <- if (dollar_y) function(x) dollar(x, accuracy = 1) else function(x) comma(x, accuracy = 0.1)
  stat_data <- stat_data %>% mutate(
    Period2 = factor(ifelse(diff_retracted <= 0, "Pre-retraction", "Post-retraction"),
                     levels = c("Pre-retraction", "Post-retraction")),
    text = paste0("Year offset: ", diff_retracted, "<br>Median: ", fmt(p50),
                  "<br>IQR: ", fmt(p25), " to ", fmt(p75),
                  "<br>10th-90th pct: ", fmt(p10), " to ", fmt(p90)))
  mean_data <- mean_data %>% mutate(
    text = paste0("Year offset: ", diff_retracted, "<br>Mean change: ", fmt(Funding_Diff)))
  ggplot(stat_data, aes(x = diff_retracted)) +
    geom_vline(xintercept = 0, color = "#d9534f", linetype = "dashed", linewidth = 0.8) +
    geom_errorbar(aes(ymin = p10, ymax = p90), width = 0.3, linewidth = 0.4, color = "gray30") +
    geom_tile(aes(y = (p25 + p75) / 2, height = p75 - p25, fill = Period2, text = text),
              width = bw, color = NA) +
    geom_segment(aes(x = diff_retracted - bw / 2, xend = diff_retracted + bw / 2, y = p50, yend = p50),
                 color = "gray30", linewidth = 0.5) +
    geom_line(data = mean_data, aes(x = diff_retracted, y = Funding_Diff), color = "black", linewidth = 0.8, group = 1) +
    geom_point(data = mean_data, aes(x = diff_retracted, y = Funding_Diff, text = text), color = "black", size = 2) +
    scale_fill_manual(values = period_pal, breaks = c("Pre-retraction", "Post-retraction")) +
    scale_x_continuous(breaks = -3:3) +
    scale_y_continuous(labels = if (dollar_y) label_dollar() else label_number(accuracy = 1)) +
    coord_cartesian(ylim = y_cap) +
    labs(x = "Years from First Retraction", y = y_label, fill = NULL) +
    dashboard_theme +
    theme(axis.line.y = element_blank(), axis.ticks.y = element_blank(),
          panel.grid.major.x = element_blank())
}

# Inline HTML reporting of a test statistic with its p-value (congruent with policy_analysis.qmd).
wilcox_txt  <- function(t) paste0("<i>V</i> = ", comma(round(unname(t$statistic))), ", ", fmt_p(t$p.value))
mcnemar_txt <- function(t) paste0("&chi;&sup2;(", unname(t$parameter), ") = ",
                                  sprintf("%.1f", unname(t$statistic)), ", ", fmt_p(t$p.value))

# Broad reason categories, identical to policy_analysis.qmd / supplementary_materials.qmd.
reason_clusters <- list(
  "Image duplication / manipulation"       = c("Duplication of/in Image", "Manipulation of Images", "Falsification/Fabrication of Image", "Concerns/Issues about Image", "Plagiarism of Image", "Unreliable Image"),
  "Formal misconduct investigation"        = c("Investigation by Company/Institution", "Investigation by ORI", "Investigation by Third Party", "Misconduct - Official Investigation(s) and/or Finding(s)", "Misconduct by Author", "Falsification/Fabrication of Data", "Falsification/Fabrication of Results"),
  "Reliability / reproducibility concerns" = c("Unreliable Results and/or Conclusions", "Unreliable Data", "Concerns/Issues about Data", "Concerns/Issues about Results and/or Conclusions", "Results Not Reproducible", "Original Data and/or Images not Provided and/or not Available"),
  "Plagiarism / duplicate publication"     = c("Plagiarism of/in Article", "Plagiarism of Text", "Plagiarism of Data", "Duplication of/in Article", "Duplication of Text", "Euphemisms for Plagiarism", "Euphemisms for Duplication", "Duplication of Data"),
  "Honest error"                           = c("Error in Data", "Error in Analyses", "Error in Results and/or Conclusions", "Error in Methods", "Error in Image"),
  "Paper mill / compromised peer review / AI generated content" = c("Compromised Peer Review", "Concerns/Issues about Peer Review", "Paper Mill", "False/Forged Authorship", "False/Forged Affiliation", "Computer-Aided Content or Computer-Generated Content")
)
reason_cat_map <- tibble(Reason = unlist(reason_clusters, use.names = FALSE),
                         Category = rep(names(reason_clusters), lengths(reason_clusters)))


